def build_all():
    out = []
    for code, th_name, en_name, note in LANGS:
        out.append(translation_issue(code, th_name, en_name, note))
    for title, body, labels in TESTS + A11Y + CONTENT + FEATURES + INFRA:
        out.append((title, body + FOOTER, labels))
    return out


def main():
    print(f"repo: {REPO}   โหมด: {'สร้างจริง' if APPLY else 'ดูก่อน (dry-run)'}\n")

    # labels
    print(f"── labels ({len(LABELS)}) ──")
    for name, color, desc in LABELS:
        if not APPLY:
            print(f"  · {name}")
            continue
        r = gh("label", "create", name, "--repo", REPO, "--color", color,
               "--description", desc, "--force", check=False)
        print(f"  {'✓' if r.returncode == 0 else '!'} {name}")

    issues = build_all()

    # หัวข้อที่มีอยู่แล้ว กันสร้างซ้ำ
    existing = set()
    r = gh("issue", "list", "--repo", REPO, "--state", "all",
           "--limit", "500", "--json", "title", check=False)
    if r.returncode == 0 and r.stdout.strip():
        existing = {i["title"] for i in json.loads(r.stdout)}

    print(f"\n── issues ({len(issues)}) ──")
    made = skipped = 0
    for title, body, labels in issues:
        if title in existing:
            print(f"  – ข้าม(มีแล้ว): {title[:62]}")
            skipped += 1
            continue
        if not APPLY:
            print(f"  · {title[:62]}  [{', '.join(labels)}]")
            continue
        args = ["issue", "create", "--repo", REPO, "--title", title, "--body", body]
        for l in labels:
            args += ["--label", l]
        r = gh(*args, check=False)
        ok = r.returncode == 0
        made += ok
        print(f"  {'✓' if ok else '✗'} {title[:62]}")
        if ok:
            print(f"      {r.stdout.strip()}")

    print(f"\nสรุป: {len(issues)} issue  ·  สร้าง {made}  ·  ข้าม {skipped}")
    if not APPLY:
        print("\nรันจริงด้วย:  python3 .github/seed-issues.py --apply")


if __name__ == "__main__":
    main()
